choose.when:
AND (
    EXISTS (SELECT 1 FROM t_data_grant g
            WHERE g.account_id = #{scope.accountId}
              AND g.object_type = 'SAMPLE' AND g.object_id = s.id)
    OR EXISTS (SELECT 1 FROM t_data_grant g
            WHERE g.account_id = #{scope.accountId}
              AND g.object_type = 'BOX' AND g.object_id = s.box_id)
    OR EXISTS (SELECT 1 FROM t_data_grant g
            WHERE g.account_id = #{scope.accountId}
              AND g.object_type = 'TASK' AND g.object_id = s.task_id)
    OR (s.location_id IS NOT NULL AND EXISTS (SELECT 1 FROM t_data_grant g
            WHERE g.account_id = #{scope.accountId}
              AND g.object_type = 'LOCATION' AND g.object_id = s.location_id))
)

mapper.select:
SELECT s.id, s.sample_no, s.task_id, t.task_no, t.task_name, s.box_id, b.box_no, s.location_id, l.location_code, s.layer_no, s.depth_top, s.depth_bottom, s.temperature, s.melt_water_ml, s.integrity_pct, s.status, s.sampled_at, s.tenant_id, (SELECT COUNT(1) FROM t_ice_layer_slice ls2 WHERE ls2.sample_id = s.id) AS slice_count FROM t_ice_core_sample s LEFT JOIN t_drill_task t ON t.id = s.task_id LEFT JOIN t_sample_box b ON b.id = s.box_id LEFT JOIN t_storage_location l ON l.id = s.location_id WHERE 1 = 1
ORDER BY s.id ASC ORDER BY s.id DESC
LIMIT #{q.limit} OFFSET #{q.offset}

SELECT ls.layer_no AS "layerNo", COUNT(1) AS "sliceCount"
FROM t_ice_layer_slice ls
WHERE 1 = 1
AND ls.location_id = #{locationId}
AND ls.layer_no > #{lastLayerNo}

GROUP BY ls.layer_no
ORDER BY ls.layer_no ASC
LIMIT #{limit}
OFFSET #{offset}
